# ultradex — CCC k0s deploy (vakr / ccc-tmp).
# Images are local tags imported via `k0s ctr images import` (imagePullPolicy: Never).
# deploy-on-host.sh dedupes glass_* keys to one ccc/glass:dev build.
#
IMG[api]="ccc/ultradex"
CTX[api]="."
FILE[api]="Dockerfile"
PREFIX[api]=""

IMG[glass]="ccc/glass"
CTX[glass]="."
FILE[glass]="apps/web/Dockerfile"
PREFIX[glass]="apps/web/"

IMG[glass_sdk]="ccc/glass"
CTX[glass_sdk]="."
FILE[glass_sdk]="apps/web/Dockerfile"
PREFIX[glass_sdk]="sdk/typescript/"

IMG[glass_ui]="ccc/glass"
CTX[glass_ui]="."
FILE[glass_ui]="apps/web/Dockerfile"
PREFIX[glass_ui]="packages/ui-svelte/"
